mapper.select:
select c.*, col.name as college_name from clazz c left join college col on c.college_id = col.id
and c.name like concat('%', #{name}, '%')
and c.college_id = #{collegeId}
and c.create_time between #{begin} and #{end}
order by c.create_time desc

mapper.update:
update clazz
name = #{name}, room = #{room}, college_id = #{collegeId}, head_teacher_id = #{headTeacherId}, update_time = #{updateTime},
where id = #{id}
